/* Conditions extracted verbatim from https://datracker.strathfield.nsw.gov.au/document/download?key=4NKe5tjLBPY=&fileName=DA2025.159 - 55-57 Abbotsford Road HOMEBUSH - Notice of Determination (Signed).PDF (conditions-extractor-2026-08-16) — export-conditions-2026-08-16. Do not hand-edit. */
registerRefData('nsw-cond-n-1923',{"id":1923,"pan":null,"ref":"10.2025.159.1","address":"55-57 Abbotsford Rd, Homebush 2140 NSW","description":"alterations to existing heritage dwelling, construction of two storey addition at rear with basement, inground swimming pool and futsal court","outcome":"approved","outcome_raw":"Approved - Delegation","outcome_source":"tracker","determined":"2026-05-18","notice_url":"https://datracker.strathfield.nsw.gov.au/document/download?key=4NKe5tjLBPY=&fileName=DA2025.159 - 55-57 Abbotsford Road HOMEBUSH - Notice of Determination (Signed).PDF","sha256":"8eadce6b2941491b3732d2d8bc6856dd4aff6596dd2f3c5384a4ef5598b67b05","pages":39,"layout":"numbered","n":96,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/1923.js","source_page":"https://datracker.strathfield.nsw.gov.au/Application/ApplicationDetails/010.2025.00000159.001","lga":"STRATHFIELD","conditions":[{"label":"1","code":null,"number":"1","title":"Compliance with Building Code of Australia and insurance requirements","text":"under Home Building Act 1989\n1. It is a condition of a development consent for development that involves\nbuilding work that the work must be carried out in accordance with the\nrequirements of the Building Code of Australia.\n2. It is a condition of a development consent for development that involves\nresidential building work for which a contract of insurance is required under\nthe Home Building Act 1989, Part 6 that a contract of insurance is in force\nbefore building work authorised to be carried out by the consent\ncommences.\n3. It is a condition of a development consent for a temporary structure used as\nan entertainment venue that the temporary structure must comply with\nPart B1 and NSW Part H102 in Volume 1 of the Building Code of Australia.\n4. In subsection (1), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for the construction certificate was made.\n5. In subsection (3), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for development consent was made.\n6. This section does not apply-\na. to the extent to which an exemption from a provision of the Building\nCode of Australia or a fire safety standard is in force under\nthe Environmental Planning and Assessment (Development\nCertification and Fire Safety) Regulation 2021, or\nb. to the erection of a temporary building, other than a temporary\nstructure to which subsection (3) applies.","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"Erection of signs","text":"1. This section applies to a development consent for development involving\nbuilding work, subdivision work or demolition work.\n2. It is a condition of the development consent that a sign must be erected in a\nprominent position on a site on which building work, subdivision work or\ndemolition work is being carried out-\na. showing the name, address and telephone number of the principal\ncertifier for the work, and\nb. showing the name of the principal contractor, if any, for the building\nwork and a telephone number on which the principal contractor\nmay be contacted outside working hours, and\nc. stating that unauthorised entry to the work site is prohibited.\n3. The sign must be-\na. maintained while the building work, subdivision work or demolition\nwork is being carried out, and\nb. removed when the work has been completed.\n4. This section does not apply in relation to-\na. building work, subdivision work or demolition work carried out\ninside an existing building, if the work does not affect the external\nwalls of the building, or\nb. Crown building work certified to comply with the Building Code of\nAustralia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"Fulfilment of BASIX commitments","text":"It is a condition of a development consent for the following that each\ncommitment listed in a relevant BASIX certificate is fulfilled-\n1. BASIX development,\nBASIX optional development, if the development application was accompanied\nby a BASIX certificate.","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"Notification of Home Building Act 1989 requirements","text":"1. This section applies to a development consent for development involving\nresidential building work if the principal certifier is not the council.\n2. It is a condition of the development consent that residential building work\nmust not be carried out unless the principal certifier for the development to\nwhich the work relates has given the council written notice of the\nfollowing-\na. for work that requires a principal contractor to be appointed-\ni. the name and licence number of the principal contractor,\nand\nii. the name of the insurer of the work under the Home\nBuilding Act 1989, Part 6,\nb. for work to be carried out by an owner-builder-\ni. the name of the owner-builder, and\nii. if the owner-builder is required to hold an owner-builder\npermit under the Home Building Act 1989-the number of\nthe owner-builder permit.\n3. If the information notified under subsection (2) is no longer correct, it is a\ncondition of the development consent that further work must not be carried\nout unless the principal certifier has given the council written notice of the\nupdated information.\n4. This section does not apply in relation to Crown building work certified to\ncomply with the Building Code of Australia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"","text":"Approved plans and supporting documentation.\nDevelopment must be carried out in accordance with the following approved\nplans and documents, except where the conditions of this consent expressly\nrequire otherwise.\nApproved Plans\nDescription Reference\nNo.\nDate Revisio\nn\nPrepared By\nSite Plan Project No.\n24-007 Dwg\nNo. DA-002\n26/0\n3/20\n26 C Urban Link\nFloor Plans Project No.\n24-007 Dwg\nNo. DA-101\n26/0\n3/20\n26 C Urban Link\nDemolition Plan Project No.\n24-007 Dwg\nNo. DA-102\n26/0\n3/20\n26 C Urban Link\nBasement Plan Project No.\n24-007 Dwg\nNo. DA-110\n26/0\n3/20\n26 C Urban Link\nGround Plan Project No.\n24-007 Dwg\nNo. DA-111\n26/0\n3/20\n26 C Urban Link\nUpper Floor Project No.\n24-007 Dwg\nNo. DA-112\n26/0\n3/20\n26 C Urban Link\nRoof Plan Project No.\n24-007 Dwg\nNo. DA-113\n26/0\n3/20\n26 C Urban Link\nStreetscape Project No.\n24-007 Dwg\nNo. DA-201\n26/0\n3/20\n26 C Urban Link\nNorth & South\nElevations\nProject No.\n24-007 Dwg\nNo. DA-202\n26/0\n3/20\n26 C Urban Link\nEast & West\nElevations\nProject No.\n24-007 Dwg\nNo. DA-203\n26/0\n3/20\n26 C Urban Link\nSection A & B Project No.\n24-007 Dwg\nNo. DA-301\n26/0\n3/20\n26 C Urban Link\nSection C - E Project No.\n24-007 Dwg\nNo. DA-302\n26/0\n3/20\n26 C Urban Link\nFutsal court\ndrawings\nProject No.\n24-007 Dwg\nNo. DA-\n1403\n26/0\n3/20\n26 C Urban Link\nSchedule of\nmaterials\nProject No.\n24-007 Dwg\nNo. DA-\n1404\n26/0\n3/20\n26 C Urban Link\nSchedule of\nmaterials\nProject No.\n24-007 Dwg\nNo. DA-\n1405\n26/0\n3/20\n26 C Urban Link\nCover sheet Dwg No. L00 24/0\n3/20\n26 C a total concept landscape\narchitects\nLandscape Plan Dwg No. L01 24/0\n3/20\n26 C a total concept landscape\narchitects\nLandscape\nReference\nImages\nDwg No. L02 24/0\n3/20\n26 C a total concept landscape\narchitects\nLandscape\ndetails\nDwg No. L03 24/0\n3/20\n26 C a total concept landscape\narchitects\nLandscape\nSpecification\nDwg No. L04 24/0\n3/20\n26 C a total concept landscape\narchitects\nCover sheet Project No.\nCSW2025.1\n38 Dwg No.\nSW-100\n23/1\n0/20\n25\n03 APEX Civil Engineers\nDesign Notes 1\nof 2\nProject No.\nCSW2025.1\n38 Dwg No.\nSW-101\n23/1\n0/20\n25\n03 APEX Civil Engineers\nDesign Notes 2\nof 2\nProject No.\nCSW2025.1\n38 Dwg No.\nSW-102\n23/1\n0/20\n25\n03 APEX Civil Engineers\nStormwater\ndesign -\nbasement plan\nProject No.\nCSW2025.1\n38 Dwg No.\nSW-200\n23/1\n0/20\n25\n03 APEX Civil Engineers\nStormwater\ndesign - ground\nfloor plan\nProject No.\nCSW2025.1\n38 Dwg No.\nSW-201\n23/1\n0/20\n25\n03 APEX Civil Engineers\nSediment &\nerosion control\nplan\nProject No.\nCSW2025.1\n38 Dwg No.\nSW-300\n23/1\n0/20\n25\n03 APEX Civil Engineers\nStandard details Project No.\nCSW2025.1\n23/1\n0/20\n25\n03 APEX Civil Engineers\n38 Dwg No.\nSW-400\nCivil driveway\ndesign\nProject No.\nCSW2025.1\n38 Dwg No.\nCIV-10\n23/1\n0/20\n25\n03 APEX Civil Engineers\nLong Section A Project No.\nCSW2025.1\n38 Dwg No.\nCIV-20\n23/1\n0/20\n25\n03 APEX Civil Engineers\nVehicle tracking Project No.\nCSW2025.1\n38 Dwg No.\nCIV-20\n23/1\n0/20\n25\n03 APEX Civil Engineers\nTypical detail Project No.\nCSW2025.1\n38 Dwg No.\nCIV-20\n23/1\n0/20\n25\n03 APEX Civil Engineers\nApproved Documentation\nDescription Reference\nNo.\nDate Revisio\nn\nPrepared By\nStructural\nEngineering\nReport\n25150-SER 2\nApril\n2026\nA Rebar Engineering PTY LTD\nGeotechnical\nInvestigation\nJ6523. 30\nMarc\nh\n2026\n- White Geotechnical Group\nSchedule of\nconservation\nworks\nJ7707_01 12.03\n.2026\n- Weir Phillips Heritage\nWaste\nManagement\nPlan\nULA-DA-\nWMP-001\n27 Augu\nst\n2020\n- Urban Link\nFlood Impact\nAssessment\nCSW2025.1\n38\n25 Octo\nber\n2024\nA APEX Civil Engineers\nBASIX\nCertificate\nA1821948 14\nNove\nmber\n2025\n- Greenworld Architectural\nDrafting\nArboricultural\nImpact\nAssessment\nAIA2/09/20\n25\n10/1\n1/20\n25 v2 Arbor Express\nIn the event of any inconsistency between the approved plans and documents,\nthe approved plans prevail.\nIn the event of any inconsistency with the approved plans and a condition of this\nconsent, the condition prevails.","stage":"general","stage_basis":"heading","page":5},{"label":"6","code":null,"number":"6","title":"Infrastructure Development Contributions","text":"Council has identified that the development will be subject to the imposition of\nDevelopment Contributions. In accordance with Council’s relevant Contributions\nPlan, the following monetary contributions are required.\nDEVELOPMENT CONTRIBUTIONS\nStrathfield Section 94A Indirect\nDevelopment Contributions Plan 2010\n$ 30,173.96\nTOTAL CONTRIBUTIONS $ 30,173.96\nIndexation\nThe above contributions will be indexed at the time of payment to reflect\ninflation, in accordance with the indices provided by the relevant Development\nContributions Plan. Indexation will be based on the CPI of 102.41 used to\ncalculate the above contribution amount.\nPlease email council council@strathfield.nsw.gov.au prior to the payment of\ns7.11 or s7.12 Contributions to confirm the indexed contribution payable and the\nform of payment that will be accepted by Council.\nTiming of Payment\nThe contribution must be paid and receipted by Council prior to the issue of the\nConstruction Certificate.\nA copy of the current Development Contributions Plans may be viewed on\nCouncil’s website www.strathfield.nsw.gov.au.","stage":"general","stage_basis":"heading","page":8},{"label":"7","code":null,"number":"7","title":"Section 138 Roads Act 1993 & Section 68 Local Government Act 1993","text":"Unless otherwise specified by a condition of this consent, this Development\nConsent does not give any approval to undertake works on public infrastructure.\nSeparate approval is required under Section 138 of the Roads Act 1993 and Section\n68 of the Local Government Act 1993 for any of the following activities carried out\nin, on or over a public road (including the footpath) listed below.\nAn application is required to be lodged and approved prior to the commencement\nof any of the following works or activities.\n(a) If any excavation is to be supported by the use of below ground (cable) anchors\nthat are constructed under Council’s roadways/footways.\n(b) Swinging or hoisting goods over any part of a public road by means of a lift,\ncrane or the like;\n(c) Establishing a “works zone”;\n(d) Placing or storing materials or equipment;\n(e) Placing or storing waste containers or skip bins;\n(f) Stormwater & ancillary to public infrastructure on private land\n(g) Erecting a structure or carrying out work\nSeparate activity approvals for (a) -(g) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the issue of the Construction\nCertificate.\n(h) Pumping water from the site into the public road;\n(i) Constructing a vehicular crossing or footpath;\n(j) Digging up or disturbing the surface of a public road (e.g. Opening the road for\nthe purpose of connections to utility providers);\n(k) Stormwater & ancillary works in the road reserve; and\n(l) Pumping concrete from a public road;\nSeparate activity approvals for (h) -(l) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the activities commencing.\nThe relevant Application Forms for these activities can be downloaded from\nCouncil’s website\nwww.strathfield.nsw.gov.au\nFor further information, please contact Council’s Customer Service Centre on (02)\n9748 9999.","stage":"general","stage_basis":"heading","page":8},{"label":"8","code":null,"number":"8","title":"Vehicular Crossing - Minor Development","text":"Constructing a vehicular crossing and footpath requires a separate approval under\nSection 138 of the Roads Act 1993 prior to the commencement of those works.\nThis approval must be obtained from Council by completing and submitting a\nworks permit application.\nThe approval for a new or modified vehicular crossing will contain the plans and\nspecifications required to construct the crossing and footpath. These works must\nbe completed prior to the issue of an Occupation Certificate.","stage":"general","stage_basis":"heading","page":9},{"label":"9","code":null,"number":"9","title":"Road Opening Permit","text":"A Road Opening Permit must be obtained from Council, in the case of local or\nregional roads, or from TFNSW in the case of State roads, for every opening of a\npublic reserve to access services including sewer, stormwater drains, water mains,\ngas mains, and telecommunications before the commencement of works in the\nroad.","stage":"general","stage_basis":"heading","page":9},{"label":"10","code":null,"number":"10","title":"Stormwater connection to Council drainage system","text":"The point of connection of the site stormwater from the silt-arrestor pit to\nCouncil’s underground pipeline is to be via gravity to a kerb inlet pit to be\nconstructed at applicant’s costs. The work is to include restoration of kerb and\ngutter adjacent to the new pit.\nBUILDING WORK","stage":"general","stage_basis":"heading","page":9},{"label":"11","code":null,"number":"11","title":"Design amendments","text":"Before the issue of a construction certificate, the certifier must ensure the\nconstruction certificate plans and specifications detail the following required\namendments to the approved plans and documents:\na) The stormwater plans shall be amended to delete the vehicular access on\nthe southeastern corner of the site.\nb) No plants in the rear yard shall exceed the height of extension (7.8m). The\nlandscape plan shall be amended accordingly.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"12","code":null,"number":"12","title":"Long Service Levy","text":"Before the issue of the relevant construction certificate the long service levy of $\n7,543.00, as calculated at the date of this consent, must be paid to the Long\nService Corporation of Council under the Building and Construction industry Long\nService Payments Act 1986 , section 34, and evidence of the payment is to be\nprovided to the certifier.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"13","code":null,"number":"13","title":"Payment of security deposits","text":"Before the issue of the relevant construction certificate, the applicant must:\na) make payment of $24,514.00 for a security deposit and $155.00 for\nAdministration Fee to the consent authority, and\nb) if a principal certifier is required to be appointed for the development -\nprovide the principal certifier with written evidence of the payment and the\namount paid.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"14","code":null,"number":"14","title":"Basix Commitments","text":"The approved BASIX Certificate must be submitted to the Principal Certifier with\nthe application for a Construction Certificate.\nAll measures and commitments as detailed in the BASIX Certificate No. A1821948\nmust be implemented on the plans lodged with the application for the\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"15","code":null,"number":"15","title":"Low Reflectivity Roof","text":"Roofing materials must be low glare and reflectivity. Details of finished external\nmaterials must be provided to the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"16","code":null,"number":"16","title":"Stormwater System","text":"The submitted stormwater plan has been assessed as a concept plan only. Final\ndetailed plans of the drainage system in accordance with Council’s Stormwater\nManagement Code and AS/NZS 3500.3: 2015 (as amended), prepared by a\nsuitably qualified professional engineer specialising in hydraulic engineering, must\nbe submitted for approval to the Principal Certifier with the Construction\nCertificate.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"17","code":null,"number":"17","title":"Erosion and sediment control plan","text":"Before the issue of a construction certificate, an erosion and sediment control\nplan must be prepared by a suitably qualified person in accordance with the\nfollowing documents and provided to the certifier or council (where a certifier is\nnot required):\na) Council’s relevant development control plan,\nb) the guidelines set out in the NSW Department of Housing manual ‘Managing\nUrban Stormwater: Soils and Construction Certificate’ (the Blue Book) (as\namended from time to time), and\nc) the ‘Guidelines for Erosion and Sediment Control on Building Sites’\n(Department of Planning, Housing and Infrastructure)\n(dated 2024, as amended from time to time)","stage":"before_cc","stage_basis":"heading","page":11},{"label":"18","code":null,"number":"18","title":"Dial Before Your Dig","text":"The applicant must contact Home | Before You Dig Australia (BYDA) to obtain a\nService Diagram prior to the issuing of the Construction Certificate. The sequence\nnumber obtained from “Dial Before You Dig” must be forwarded to Council’s\nEngineers for their records.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"19","code":null,"number":"19","title":"Structural Details","text":"Engineer’s details for all reinforced concrete work, structural beams, columns &\nother structural members must be prepared by a suitably qualified practising\nStructural Engineer. These details are to be submitted to the Principal Certifier\nfor approval.\nA copy must be forwarded to Council where Council is not the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"20","code":null,"number":"20","title":"Off Street Parking - Compliance with AS2890","text":"All driveways, access ramps, vehicular crossings and car parking spaces must be\ndesigned and constructed in accordance with the current version of Australian\nStandards, AS 2890.1 (for car parking facilities), AS 2890.6 (parking for people with\ndisabilities) and AS 2890.2 (for commercial vehicle facilities).","stage":"before_cc","stage_basis":"heading","page":11},{"label":"21","code":null,"number":"21","title":"Construction Site Management Plan","text":"Before the issue of a construction certificate, a construction site management\nplan must be prepared, and provided to the certifier or council (where a certifier\nis not required). the plan must include the following matters:\na) The location and materials for protective fencing and hoardings on the\nperimeter of the site;\nb) Provisions for public safety;\nc) Pedestrian and vehicular site access points and construction activity zones;\nd) Details of construction traffic management including:\ni) Proposed truck movements to and from the site;\nii) Estimated frequency of truck movements; and\niii) Measures to ensure pedestrian safety near the site;\ne) Details of bulk earthworks to be carried out;\nf) The location of site storage areas and sheds;\ng) The equipment used to carry out works;\nh) The location of a garbage container with a tight-fitting lid;\ni) Dust, noise and vibration control measures;\nj) The location of temporary toilets;\nk) The protective measures for the preservation of trees on-site and in\nadjoining public areas including measures in accordance with:\ni) AS 4970 - Protection of trees on development sites;\nii) An applicable Development Control Plan;\niii) An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on-site at all times\nwhile work is being carried out","stage":"before_cc","stage_basis":"heading","page":12},{"label":"22","code":null,"number":"22","title":"Waste Management Plan - an approved document of this consent","text":"Before the issue of a construction certificate, a waste management plan for the\ndevelopment must be provided to the certifier or council (where a certifier is not\nrequired).","stage":"before_cc","stage_basis":"heading","page":12},{"label":"23","code":null,"number":"23","title":"Tree Bond","text":"A tree bond (calculated in accordance with Council’s adopted Fees and Charges)\nmust be paid to Council, prior to the issue of a Construction Certificate.\nTree\nnumber\nSpecies Name Height Bond Fee\nTree 2 Lophostemon confertus 10.0 metres $23,698.00\nTree 3 Lophostemon confertus 9.0 metres $11, 849.00\nA tree bond administration fee of $155.00 applies.\nThe deposit is required as security against any damage to existing trees to be\nretained on Council’s Road reserve, during works on the site. The applicant must\nbear the cost of all restoration works to Council’s property damaged during the\ncourse of this development.\nA Tree Protection fence consisting of a fully supported chainmesh fence 1.8\nmetres height x 2 metres clear of the base of the tree at any one point must be\nerected around the nominated street trees in front of 55-57 Abbotsford Road and\nany trees in adjacent reserves and parks if applicable, unless otherwise specified\nin AS4970-2025.\nThe Tree Protection fence is to extend up to the back of the kerb and to the edge\nof the footpath,\nTree Protection fence is to be in place prior to commencement of demolition/\nconstruction works.\nPayment may be accepted in the form of a bank cheque, credit card or bank\nguarantee. An administration fee applies to all bonds in accordance with Council’s\nadopted Fees and Charges.\nA request for refund of the Tree Bond must be made in writing.\nTree Bonds may be forfeited if a tree is dead, made dangerous or has been\nterminally damaged, or will be held until tree/s have fully recovered from the\nconstruction damage or were replacement/planted trees have become fully\nestablished and are over 6 metres in height.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"24","code":null,"number":"24","title":"Landscape Plans","text":"All landscape works must be carried out in accordance with the approved\nlandscape plans.\nFollowing notes are to be placed on all Architectural Drawings:\n“Proposed new vehicle crossover, on the western boundary fence line, to be\ninstalled before demolition/ construction commences.\nProposed new vehicle crossover to be hand dug using tree sensitive equipment ,\nwhen inside the SRZ of the neighbouring trees, and under the supervision of the\nProject Arborist.\nNo roots are to be cut without the approval from Council’s Urban Forest\nSupervisor.\nAll construction vehicles to access the site via the new vehicle crossover, for the\nentire development time, to ensure protection of the existing Street Trees and\nneighbouring trees.”","stage":"before_cc","stage_basis":"heading","page":13},{"label":"25","code":null,"number":"25","title":"Tree Removal/Pruning Prohibited","text":"The removal or pruning (branches or roots) of any trees on the subject property\n(excluding those approved for removal in these conditions or species on Council’s\nexempt species list), Council’s public footway, public reserves or on neighbouring\nproperties must not be undertaken other than in accordance with the express\nprovisions of this consent.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"26","code":null,"number":"26","title":"Tree Protection and Retention","text":"The following trees are to be protected throughout the course of all demolition and\nconstruction works. Tree protection is to be in place prior to commencement of\ndemolition works.\nTree No. Tree Species Location of Tree TPZ\nTree 1 Lophostemon\nconfertus\nCouncil Verge 6.00 metres\nTree 2 Lophostemon\nconfertus\nCouncil Verge 7.32 metres\nTree 3 Lophostemon\nconfertus\nCouncil Verge 5.88 metres\nTree 4 Lophostemon\nconfertus\nCouncil Verge 7.20 metres\nTree 7 Jacaranda\nmimosifolia\nNeighbouring Tree 5.50 metres\nTree 8 Jacaranda\nmimosifolia\nNeighbouring Tree 4.56 metres\nTree 9 Melaleuca citrina Healthy site tree 4.30 metres\nTree 10 Lagerstroemia\nindica\nHealthy site tree 4.00 metres\nTree 11 Jacaranda\nmimosifolia\nHealthy site tree 3.80 metres\nTree 12 Jacaranda\nmimosifolia\nHealthy site tree 3.40 metres\nTree 13 Deciduous Tree- not\nidentified in AIA\nReport\nNeighbouring Tree 2.00 metres\nTree 14 Deciduous Tree- not\nidentified in AIA\nReport\nNeighbouring Tree 2.00 metres\nTree 15 Ligustrum vulgare. Neighbouring Tree 3.00 metres\nTree 16 Brachychiton\nacerifolius\nNeighbouring Tree 4.60 metres\nTree 17 Ligustrum vulgare. Neighbouring Tree 3.00 metres\nTree 18 Lagerstroemia\nindica\nNeighbouring Tree 2.00 metres\nTree 19 Ligustrum vulgare. Neighbouring Tree 2.00 metres\nTree 20 Murraya paniculata Neighbouring Tree 3.00 metres\nTree 21 Jacaranda\nmimosifolia\nNeighbouring Tree 2.70 metres\nTree 22 Cupressus sp. Neighbouring Tree 4.20 metres\nA project arborist (min. Qualification AQF5) is to be engaged throughout the\ndemolition and construction process.\nAll works within Tree TPZ is to be by hand tools only as per the Aboricultural\nMethod Statement of the AIA Report.\nA Project Arborist must be present on -site during the stages of construction\nwhen works are being undertaken that could impact on the tree canopy or root\nzone within the Tree Protection Zone to implement the tree protection measures\nas required.\nNo services shall be installed within the Tree Protection Zone of the tree unless\napproved by Council. Tree protection fencing shall be kept in place during\ndemolition, construction and also have a sign displaying ‘Tree Protection Zone’\nattached to the fence and must also include the name and contact details of the\nProject Arborist.\nWhere the Tree Protection Zone of trees on site or adjoining sites become\ncompromised by any excavation works, the Project Arborist shall be consulted to\nestablish the position of any major roots and determine the necessary measures\nto protect these roots. The recommendations of the Project Arborist shall be\nsubmitted to Council prior to any further demolition or construction works taking\nplace","stage":"before_cc","stage_basis":"heading","page":14},{"label":"27","code":null,"number":"27","title":"Tree Removal & Replacement","text":"Tree removal\nPermission is granted for the removal of the following trees:\nTree No. Tree species Location\nTree 5 Phoenix canariensis Side setback\nTree 6 Jacaranda mimosifolia Side setback\nNo Permission is granted for the removal of any other trees on site.\nGeneral Tree Removal Requirements\nAll tree removal work must be undertaken by a minimum Certificate 3 (AQF 3)\nqualified Arborist who is currently a member or eligible for membership to\nArboriculture Australia (AA) or the Tree Contractors Association Australia\n(TCAA), to ensure that removal is undertaken in a safe manner and complies\nwith the AS 4373-2007 - Pruning of Amenity Trees and Amenity Tree Industry\nCode of Practice (Safework NSW, August 1998).\nTree Replacement\nAll trees permitted to be removed by this consent must be replaced 2 trees for\neach tree removed by species selected from Council’s Suggested Tree Species List\nand must be able to achieve a minimum mature height of 10 height in metres.\nReplacement trees must be a minimum 75 litre container size. Trees are to meet\nthe requirements of AS 2303: 2018- Tree Stock for Landscape Use. Trees must be\ntrue to type, healthy and vigorous at time of delivery and planting, must be pest\nand disease free, free from injury and wounds and self-supporting; and must be\nmaintained until maturity.\nAll trees must be staked and tied with a minimum of three (3) hardwood stakes.\nTies must be hessian and fixed firmly to the stakes, one tie at half the height of\nthe main stem, others as necessary to stabilise the plant.\nTrees within lawn areas or street verges must have Tree Guard bark protectors\ninstalled around the base of trunks to protect from damage by trimmers and\nmowers.\nRoot deflection barriers having a minimum depth of 600mm are to be installed\nadjacent to all footpaths and driveways.\nSoil conditioner, fertilizer, and moisture retention additives must be applied in\naccordance with manufacturer’s recommendations, and mixed into the\nbackfilling soil after planting tree/s.\nA minimum 75mm depth of organic mulch must be placed around the tree,\nextending to a minimum radius 0.5m from the base of the trunk. Mulch shall be\n‘dished’ around the base of the tree’s trunk.\nDetails demonstrating compliance must be demonstrated to the Principal\nCertifier, prior to the issue of any Occupation Certificate.","stage":"before_cc","stage_basis":"heading","page":15},{"label":"28","code":null,"number":"28","title":"Pump-Out System Design for Stormwater Disposal","text":"The design of the pump-out system for stormwater disposal will be permitted for\ndrainage of basement areas only, and must be designed in accordance with the\nfollowing criteria:\n(a) The pump system must consist of two pumps, connected in parallel, with\neach pump being capable of emptying the holding tank at the rate equal\nto the rate of inflow for the one -hour duration storm. The holding tank\nmust be capable of holding four hour’s run off from a one-hour duration\nstorm of the 1 in 100 year storm;\n(b) The pump system must be regularly maintained and serviced, every six\n(6) months; and\n(c) Any drainage disposal to the street gutter from a pump system must have\na stilling sump provided at the property line, connected to the street\ngutter by a suitable gravity line.\nDetails and certification of compliance from a suitably qualified professional\nengineer specialising in hydraulic engineering must be provided to the Principal\nCertifier for approval with the Construction Certificate application.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"29","code":null,"number":"29","title":"Geotechnical Report","text":"The applicant must submit a Geotechnical Report, prepared by a suitably qualified\nprofessional engineer specialising in geotechnical engineering. The Geotechnical\nReport must address dilapidation reports, all site works and construction. This is\nto be su bmitted to the Principal Certifier and Council (where Council is not the\nCertifier) before the issue of the Construction Certificate and must include:\n(a) Investigations certifying the stability of the site and specifying the design\nconstraints to be placed on the foundation, any earthworks, stabilization\nworks and any excavations.\n(b) Dilapidation Reports on the adjoining properties including, but not limited to\nthe existing heritage listed dwelling prior to any excavation of site works. The\nDilapidation Report must include assessments on, but not limited to, the\ndwellings at those addresses and any external paths, grounds etc. This must\nbe submitted to the Principal Certifier and the adjoining residents as part of\nthe application for the Construction Certificate. Adjoining residents must be\nprovided with the report five (5) working days prior to any works on the site.\n(c) On-site guidance by a vibration specialist during the early part of excavation.\n(d) Measures to minimise vibration damage and loss of support to other\nbuildings. Where possible any excavation into rock is to be carried out with\ntools such as rock saws which reduce vibration to adjoining buildings and\nassociated structures. Where a hydraul ic hammer is to be used within 30\nmetres of any building (other than a path or a fence) the report must detail\nthe maximum size of hammer to be used and provide all reasonable\nrecommendations to manage impacts.\n(e) Sides of the excavation must be piered prior to any excavation occurring to\nreinforce the walls of the excavation to prevent any subsidence to the\nrequired setbacks and neighbouring sites.","stage":"before_cc","stage_basis":"heading","page":16},{"label":"30","code":null,"number":"30","title":"Compliance with Swimming Pool Act 1992","text":"The alterations and additions to the dwelling house subject of this consent must\nnot generate any non-compliance with the Swimming Pools Act 1992, Swimming\nPool Regulation 2018, and the Building Code of Australia. Details of compliance\nmust be the illustra ted on the plans lodged with the application for the\nConstruction Certificate","stage":"before_cc","stage_basis":"heading","page":17},{"label":"31","code":null,"number":"31","title":"Swimming Pools - Use and Maintenance","text":"The following apply to the construction, use and maintenance of swimming pools\nand spas:\n(a) No ground level may be raised or filled except where shown specifically on\nthe approved plans;\n(b) All pool or spa waste water is to be discharged to the sewer according to the\nrequirements of Sydney Water;\n(c) The swimming pool must not be used for commercial or professional\npurposes;\n(d) Paved areas must be designed to ensure drainage flows to the landscaped\nareas or a suitable lawful drainage system; and\n(e) Any lighting external to the pool or spa must be arranged to minimise glaring\nnuisance to adjoining owners.","stage":"before_cc","stage_basis":"heading","page":17},{"label":"32","code":null,"number":"32","title":"Street and Reserve Tree Protection and Retention","text":"A protective fence consisting of a fully supported chainmesh fence 1.8 metres\nheight x 2 metres clear of the base of the tree at any one point must be erected\naround the nominated street trees in front of 55-57 Abbotsford Road, Homebush\nand any trees in ad jacent reserves and parks if applicable, unless otherwise\nspecified in AS4970-2009. The fence is to extend up to the back of the kerb and\nto the edge of the footpath. No services shall be installed within the Tree\nProtection Zone of the tree unless approved by Council. Tree protection fencing\nshall be kept in place during demolition, construction and also have a sign\ndisplaying ‘Tree Protection Zone’ attached to the fence and must also include the\nname and contact details of the Project Arborist.\nNo soil, fill, building materials or waste should be placed or disposed of within the\nprotection area.\nTree No. Tree Species Location of Tree\nTree 1 Lophostemon confertus Council Verge\nTree 2 Lophostemon confertus Council Verge\nTree 3 Lophostemon confertus Council Verge\nTree 4 Lophostemon confertus Council Verge\nShould replacement or repair of the public footpath or vehicle crossing within the\nTree Protection Zone area of a street tree be required, Council’s Urban Forest\nSupervisor is to be notified (with minimum 24hrs notice) of the intent to\nundertake the works and is to attend a site inspection after the existing footpath\nhas been lifted but prior to any preparation works for laying of the new path. No\nstreet tree roots are to be cut without the Approval of Council. Failure to comply\nwith this condition may result in the forfeiting of the Tree Bond should the street\ntree’s health or structure be compromised.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"33","code":null,"number":"33","title":"Detailed Stormwater Design","text":"The submitted stormwater plan has been assessed as a concept plan only. A\ndetailed drainage design supported by a catchment area plan and drainage\ncalculations (including a Hydraulic Grade Line Analysis) in accordance with\nCouncil’s Stormwater Management Code must be submitted to and approved by\nthe Principal Certifier with the Construction Certificate Application..","stage":"before_cc","stage_basis":"heading","page":18},{"label":"34","code":null,"number":"34","title":"Compliance with Flood Study","text":"The development must be designed to conform to the recommendations and\nconclusions of the submitted flood study prepared by Apex Civil Engineers dated\n24/10/25\nThis must include, but not be limited to, any recommendations for the following:\n(a) Minimum floor levels\n(b) Fencing\n(c) Site regrading\n(d) Overland flow path construction\n(e) Protection of the basement from inundation of surface waters\nEvidence from a suitably qualified professional engineer that specialises in\nhydraulic engineering that all design requirements have been adhered to must be\nsubmitted to the Principal Certifier with the Construction Certificate application.","stage":"before_cc","stage_basis":"heading","page":18},{"label":"35","code":null,"number":"35","title":"Building Works to Comply with BCA - Heritage Buildings or Buildings Within","text":"Conservation Area.\nAny building works required to achieve compliance with the Building Code of\nAustralia (BCA) or other applicable standards, which are not shown on the\napproved plans, must not damage or alter existing heritage fabric or significant\nbuilding features.\nWhere such works may impact heritage fabric, detailed plans and specifications\nmust be submitted to and approved by Council’s Manager Planning & Place prior\nto the issue of a Construction Certificate.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"36","code":null,"number":"36","title":"Schedule of External Colours and Finishes (Houses)","text":"Prior to the issue of a Construction Certificate, a detailed schedule of all external\nmaterials, colours and finishes for the development, including but not limited to\nwalls, windows, doors, screening elements, fencing and roofing materials, must\nbe submitted to and approved by Council’s Manager Planning & Place.\nThe external colour scheme must incorporate colours with a hue and tonal\nrelationship that is sympathetic to and complements the Federation period\ncharacter of the Local Heritage Item and the surrounding heritage conservation\narea.\nThe submitted documentation must:\na) show the distribution and application of all colours and materials on the\nelevation drawings;\nb) specify all paint types, finishes and material treatments; and include\ncolour swatches, product names and colour codes for all proposed\nfinishes.\nIn preparing the colour scheme, reference is to be made to the publication\nColour Schemes for Old Australian Houses by Ian Evans, Clive Lucas and Ian\nStapleton, or an equivalent heritage colour guide, to ensure an appropriate\nheritage outcome is achieved.\nThe approved materials and colour scheme must be implemented and\nmaintained for the life of the development.","stage":"before_cc","stage_basis":"heading","page":19},{"label":"37","code":null,"number":"37","title":"General Heritage","text":"(a) The proposed works must be carried out in a manner that minimises\ndemolition, alterations, and new penetrations or fixings to the original fabric\nof the existing building which is listed as a Local Heritage Item in Strathfield\nLEP.\n(b) The fabric and features of the existing building (internal and external) to be\nretained by the proposal must be properly protected during the process of\nany demolition and construction works.\n(c) All conservation (existing house) and adaption (extension) works must be in\naccordance with the Articles of the Australian ICOMOS Burra Charter 1999.\n(d) New services in the existing building must be surface mounted rather than\nchased-in to existing walls to minimise impact on heritage fabric.\n(e) Appropriately qualified tradesperson who are skilled and experienced in\ntraditional building and engineering trades must be commissioned to carry\nout the proposed scope of works and as outlined in the Schedule of\nConservation Works by Weirs Phillip Hertiage, (Draft 12.03.2026).\n(f) The new internal and external openings (doors, doorways, windows, window\nframes) to the existing building must match the original material.\n(g) Where internal partitions meet external walls they must abut window\nmullions, columns or other such building elements and not glazing.\n(h) The re-roofing of the existing building with slate tiles must retained as many\nof the original slate tiles as possible and match the slates where tiles are\nreplaced due to failure.\n(i) Original driveways and footpath crossings must not be relocated.\n(j) Original or early garden layouts that contribute to the streetscape or to the\nsignificance of the heritage item must be protected and not to be altered.\n(k) Modern technologies may only be provided in accordance with State\nEnvironmental Planning Policy Transport and Infrastructure.\n(l) Original fencing styles and materials must be repaired and retained.\n(m) Original door and window joinery visible from the Public Domain is to be\nconserved.","stage":"before_cc","stage_basis":"heading","page":20},{"label":"38","code":null,"number":"38","title":"Heritage Conservation Works","text":"All conservation, restoration and adaptation works associated with the heritage\nbuilding must be carried out in accordance with the principles and guidelines of\nthe Australia ICOMOS Burra Charter 2013 (as amended from time to time).\nAll works are to be undertaken by suitably qualified and experienced contractors\nand tradespersons with demonstrated expertise in traditional building\nconservation techniques and heritage construction practices relevant to the age,\nfabric and significance of the heritage item.\nThe approved conservation works must be progressively inspected by the\napplicant’s nominated Heritage Consultant/Advisor during the course of\nconstruction to ensure compliance with the approved plans, heritage\ndocumentation and conservation methodology.\nWritten confirmation from the Heritage Consultant/Advisor certifying that the\nconservation and adaptation works have been completed in accordance with\nthe approved documentation and the principles of the Burra Charter must be\nsubmitted to Council’s Manager Planning & Place prior to the issue of any\nOccupation Certificate or commencement of the approved use, whichever\noccurs first.\nAll conservation works must be completed to the satisfaction of Council’s\nManager Planning & Place.","stage":"before_cc","stage_basis":"heading","page":20},{"label":"39","code":null,"number":"39","title":"Photographic Archival Documentation (Major Works)","text":"Prior to the Construction Certificate being issued, an archival photographic\nrecording of the Local Heritage Item, in particular the existing building must be\nprepared to the satisfaction of Council’s Heritage Planner. The recording must be\nin a digital fo rm, prepared in accordance with NSW Heritage Offices’\n“Photographic Recording of Heritage Items using Film or Digital Capture”\nguideline. One copy of the record is to be submitted to Council to be lodged with\nCouncil’s Archives)\nThe archival documentation, and the number and type of selected enlarged\nphotographs required will be determined by the significance and quality of the\nbuilding or structure. For a scope of work, refer to Council’s Heritage Planner to\ndetermine the particular architectural and design features of the building or site\nthat need to be recorded.\nAs significant fabric may remain concealed and only be exposed during\nconstruction works, the archival recording must be undertaken in stages as\nconsidered appropriate by the conservation architect commissioned for the\nproject.\nThe archival recordings must be submitted to the satisfaction of Council’s\nManager Planning & Place as follows:\n(a) Prior to the removal of any significant building fabric or furnishings from the\nsite, prior to the commencement of any work on site and prior to a\nConstruction Certificate being issued.\n(b) Significant building fabric or furnishings that are exposed during demolition\nor construction and after work has been completed on site prior to any\nOccupation Certificate being issued.\nThe form of recording is to be a photographic documentation of the site and its\ncontext, and the exteriors and interiors of the existing building(s) photographed,\nwhere appropriate, using a camera/lens capable of ‘perspective correction’.\n(c) For each of the archival recordings listed above in (a) and (b), the digital form\nof the recording must be as follows:\ni. The Development Application number and the Condition of Consent\nnumber must be noted.\nii. Include a summary report detailing the project description, date and\nauthorship of the photographic record, method of documentation and\nlimitations of the photographic record.\niii. The electronic images are to be taken with a minimum 8 megapixel\ncamera, saved as JPEG TIFF or PDF files with a size of approximately 4 -\n6MB, and cross referenced to the digital catalogue sheets and base plans.\nChoose only images that are necessary to docum ent the process, and\navoid duplicate images.\niv. Include written confirmation, issued with the authority of both the\napplicant and the photographer that Strathfield Council is granted a\nperpetual non-exclusive licence to make use of the copyright in all images\nsupplied, including the right to make copies available to third parties as\nthought they were Council images. The signatures of both the applicant\nand the photographer must be included.\n(d) The report can be submitted on a USB, in PDF/A format (created directly from\nthe digital original), with a digital catalogue of images with the following data for\neach: DOS title, image subject/description and data photograph taken.","stage":"before_cc","stage_basis":"heading","page":21},{"label":"40","code":null,"number":"40","title":"Reuse of Significant Building Elements","text":"Prior to the issue of a Construction Certificate, a detailed Salvage and Reuse Plan\nmust be submitted to and approved by Council’s Manager Planning & Place.\nOriginal building elements, including but not limited to bricks, sandstone blocks,\nverandah thresholds, wall vents, ceiling roses and timber joinery, must be\ncarefully removed, retained and reused within the development wherever\npracticable, or recycled th rough an appropriate heritage building material\nrecycling facility.\nThe plan must include:\na) a schedule of materials to be salvaged;\nb) methods for the careful removal, handling and storage of heritage fabric;\nc) the location of designated on-site stockpile areas; and\nd) details of the proposed reuse or recycling of salvaged materials.\nAll works must be undertaken by suitably qualified tradespersons experienced in\nheritage conservation and carried out to the satisfaction of Council’s Manager\nPlanning & Place.","stage":"before_cc","stage_basis":"heading","page":22},{"label":"41","code":null,"number":"41","title":"Internal fence and gate to basement entrance","text":"Prior to the issue of a Construction Certificate, amended plans must be submitted\nto and approved by Council’s Manager Planning & Place demonstrating that the\ninternal fence and gate structure located between the western side of the existing\ndwelling and t he western boundary, associated with the basement entry, has\nbeen reduced in height to match the approved height of the front fence.\nThe fence and gate structure must be designed and constructed in a style,\nmaterial palette and detailing that is sympathetic to the Federation period\ncharacter of the Local Heritage Item and the Abbotsford Road Heritage\nConservation Area.\nThe approved fence and gate must be installed prior to the issue of any\nOccupation Certificate and maintained thereafter to the satisfaction of Council.","stage":"before_work","stage_basis":"heading","page":23},{"label":"42","code":null,"number":"42","title":"Planter boxes to extension","text":"Prior to the issue of a Construction Certificate, amended landscape plans must be\nsubmitted to and approved by Council’s Manager Planning & Place demonstrating\nthat the planter boxes above the basement are of sufficient depth and soil volume\nto support the long-term growth and survival of the proposed vegetation and\ntrees.\nThe selected planting must achieve a mature height and density sufficient to\nscreen the ground floor extension and soften the transition between the ground\nand first-floor levels.","stage":"before_work","stage_basis":"heading","page":23},{"label":"43","code":null,"number":"43","title":"Demolition & Asbestos","text":"The demolition work must comply with the provisions of Australian Standard\nAS2601:2001 - Demolition of Structures, NSW Work Health & Safety Act 2011 and\nthe NSW Work Health & Safety Regulation 2011 . The work plans required by\nAS2601:2001 must be accompanied by a written statement by a suitably qualified\nperson that the proposals contained in the work plan comply with the safety\nrequirements of the Standard. The work plans and the safety statement must be\nsubmitted to the Principal Certifier prior to the commencement of works.\nFor demolition work which involves the removal of asbestos, the asbestos\nremoval work must be carried out by a licensed asbestos removalist who is\nlicensed to carry out the work in accordance with the NSW Work Health & Safety\nAct 2011 and the NSW Work Health & Safety Regulation 2011 unless specified in\nthe Act or Regulation that a license is not required.\nAll demolition work including the removal of asbestos, must be undertaken in\naccordance with the Demolition Code of Practice (NSW Work Cover July 2015)","stage":"before_work","stage_basis":"heading","page":23},{"label":"44","code":null,"number":"44","title":"Demolition Notification Requirements","text":"The following notification requirements apply to this consent:\n(a) The builder must notify adjoining residents five (5) working days prior to\ndemolition. Such notification will be a clearly written note giving the date\ndemolition will commence, contact details of the builder, licensed asbestos\ndemolisher and the appropri ate regulatory authority. Notification must be\nplaced in the letterbox of every premises (including every residential flat or\nunit, if any) either side and immediately at the rear of the demolition site.\n(b) Five (5) working days prior to demolition, the builder must provide written\nnotification to Council advising of the demolition date, details of the SafeWork\nlicensed asbestos demolisher and the list of residents advised of the\ndemolition.\n(c) On demolition sites where buildings to be demolished contain asbestos, a\nstandard commercially manufactured sign containing the words “DANGER\nASBESTOS REMOVAL IN PROGRESS” measuring not less than 400mm x\n300mm must be erected in a prominent visible position (from street frontage)\non the site. The sign must be erected prior to demolition work commencing\nand will remain in place until such time as all asbestos material has been\nremoved from the site to an approved waste facility.","stage":"before_work","stage_basis":"heading","page":24},{"label":"45","code":null,"number":"45","title":"Demolition Work Involving Asbestos Removal","text":"Work involving bonded asbestos removal work (of an area of more than 10 square\nmetres) or friable asbestos removal work must be undertaken by a person who\ncarries on a business of such removal work in accordance with a licence under\nclause 458 of the Work Health and Safety Regulation 2011","stage":"before_work","stage_basis":"heading","page":24},{"label":"46","code":null,"number":"46","title":"Utility Arrangements","text":"Arrangements must be made with utility authorities in respect to the services\napplied those authorities to the development. The cost associated with the\nprovision or adjustment of services within the road and footway areas will be at\nthe applicant’s expense.","stage":"before_work","stage_basis":"heading","page":24},{"label":"47","code":null,"number":"47","title":"Erosion and sediment controls in place","text":"Before any site work commences, the principal certifier or council (where a\nprincipal certifier is not required), must be satisfied the erosion and sediment\ncontrols in the erosion and sediment control plan which was provided to the\nprincipal certifier or council (where a principal certifier is not required) are in\nplace. these controls must remain in place until any bare earth has been\nrestabilised in accordance with the\nerosion and sediment control plan.","stage":"before_work","stage_basis":"heading","page":24},{"label":"48","code":null,"number":"48","title":"Tree protection measures","text":"Before any site work commences, the principal certifier, or council where a\nprincipal certifier is not required, must be satisfied the measures for tree\nprotection detailed in the construction site management plan are in place.","stage":"before_work","stage_basis":"heading","page":25},{"label":"49","code":null,"number":"49","title":"Dilapidation report","text":"Before any site work commences, a dilapidation report must be prepared by a\nsuitably qualified engineer detailing the structural condition of adjoining\nbuildings, structures or works and public land, to the satisfaction of the principal\ncertifier or council (where a principal certifier is not required).\nwhere access has not been granted to any adjoining properties to prepare the\ndilapidation report, the report must be based on a survey of what can be\nobserved externally and demonstrate, in writing, to the satisfaction of the\nprincipal certifier or council (where a principal certifier is not required), that all\nreasonable steps were taken to obtain access to the adjoining properties.\nNo less than 7 days before any site work commences, adjoining building owner(s)\nmust be provided with a copy of the dilapidation report for their property(ies) and\na copy of the report(s) must be provided to council (where council is not the\nprincipal certifier) at the same time.","stage":"before_work","stage_basis":"heading","page":25},{"label":"50","code":null,"number":"50","title":"Dust Control","text":"Where a dust nuisance is likely to occur, suitable screens and barricades must be\nerected during the demolition, excavation and building works. Water sprays must\nbe used on the site to reduce the emission of dust. Screening must consist of a\nminimum 2 metr es height of shade cloth or similar material secured to a chain\nwire fence or the like and must be modified as required should it fail to adequately\ncontrol any dust nuisance.","stage":"before_work","stage_basis":"heading","page":25},{"label":"51","code":null,"number":"51","title":"Vehicular Access to site","text":"Only one (1) vehicular access is permitted to site. Any additional vehicular access\npoints are to be made redundant, and the layback is to be removed and\nreplaced by kerb and gutter.","stage":"before_work","stage_basis":"heading","page":26},{"label":"52","code":null,"number":"52","title":"Disposal of Surplus Salvaged Materials","text":"Prior to the commencement of any demolition works, a Salvage Methodology\nPlan must be submitted to and approved by Council’s Manager Planning & Place.\nThe plan must identify the traditional building materials and heritage items\nproposed to be salvaged, retained, reused or recycled, including but not limited\nto bricks, roof tiles, timber, joinery and laundry-related objects.\nAll salvage works must be carried out carefully and in accordance with the\napproved Salvage Methodology Plan to minimise damage to heritage fabric.","stage":"before_work","stage_basis":"heading","page":26},{"label":"53","code":null,"number":"53","title":"Materials for Making Good","text":"New materials for making good and repairs must match the existing in terms of\ncolours, finishes, sizes, profile and properties.","stage":"before_work","stage_basis":"heading","page":26},{"label":"54","code":null,"number":"54","title":"Use of Heritage Consultant - Major Development","text":"(a) A suitably qualified and experienced heritage consultant must be\ncommissioned to work with the consultant team throughout the design\ndevelopment, contract documentation and construction stages of the\nproject. The conservation architect is to be involved in the resolution of all\nmatters where existing significant fabric and spaces are to be subject to\npreservation, restoration, reconstruction, adaptive reuse, recording and\ndemolition. The heritage consultant must be provided with full access to the\nsite and authorised by the applicant to respond directly to Council where\ninformation or clarification is required regarding the resolution of heritage\nissues throughout the project.\n(b) Evidence and details of the above commission on the above terms must be\nprovided to Council’s Heritage Planner prior to the commencement of any\nworks or demolition on site.\n(c) Throughout the documentation and construction stages of the approved\nworks the heritage consultant is to:\ni. Undertake site inspections of not less than fortnightly intervals.\nii. Maintain a diary of site inspections that includes photographs of the\nworks, details of heritage advice and decisions arising out of each\ninspection and any further physical evidence uncovered during the\nworks.\niii. Compile a final report, including the diary, verifying how the heritage\nconditions have been satisfied, and the works completed in accordance\nwith the Conservation Management Plan.","stage":"before_work","stage_basis":"heading","page":26},{"label":"55","code":null,"number":"55","title":"Hours of work","text":"Site work must only be carried out between the following times -\nFor building construction and delivery of machinery and materials from 7:00am\nto 5:00pm on Monday to Saturday (excluding Public Holidays)\nFor demolition, excavation and/or construction works that involve heavy\nmachinery, noisy trades, or the like from 7:00am to 5:00pm on Monday to Friday\n(excluding Public Holidays)\nSite work is not to be carried out outside of these times except where there is an\nemergency, or for urgent work directed by a police officer or a public authority.","stage":"during_work","stage_basis":"heading","page":27},{"label":"56","code":null,"number":"56","title":"Ground Levels and Retaining Walls","text":"The ground levels of the site must not be excavated, raised or filled and retaining\nwalls constructed on the allotment boundary, except where indicated on\napproved plans or approved by Council.","stage":"during_work","stage_basis":"heading","page":27},{"label":"57","code":null,"number":"57","title":"Cost of Work to be Borne by the Applicant","text":"The applicant must pay the cost of all works associated with the construction of\nthe development that occurs on Council property. Care must be taken to protect\nCouncil’s roads, including the made footway, kerbs, etc, and where plant and\nvehicles enter the site, the footway must be protected against damage by deep -\nsectioned timber members laid crosswise, held together by hoop iron straps and\nchamfered at their ends. This construction must be maintained in a state of good\nrepair and condition throughout the course of construction.","stage":"during_work","stage_basis":"heading","page":27},{"label":"58","code":null,"number":"58","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved\nremoval, relocation or reconstruction of infrastructure (including ramps,\nfootpaths, kerb and gutter, light poles, kerb inlet pits, service provider pits, street\ntrees or any other infrastructure in the street footpath area) must be paid as\ndirected by the consent authority.","stage":"during_work","stage_basis":"heading","page":27},{"label":"59","code":null,"number":"59","title":"Obstruction of Road or Footpath","text":"The use of the road or footpath for the storage of any building materials, waste\nmaterials, temporary toilets, waste or skip bins, or any other matter is not\npermitted unless separately approved by Council under Section 138 of the Roads\nAct 1993 and under Section 68 of the Local Government Act 1993 . Penalty\ninfringement Notices may be issued for any offences and severe penalties apply.","stage":"during_work","stage_basis":"heading","page":28},{"label":"60","code":null,"number":"60","title":"Construction Management Plan","text":"The builder must ensure that the approved Construction Traffic Management Plan\nis to be strictly complied with and kept on site at all times during construction\nworks.","stage":"during_work","stage_basis":"heading","page":28},{"label":"61","code":null,"number":"61","title":"Procedure for critical stage inspections","text":"While building work is being carried out, the work must not continue after each\ncritical stage inspection unless the principal certifier is satisfied the work may\nproceed in accordance with this consent and the relevant construction certificate.","stage":"during_work","stage_basis":"heading","page":28},{"label":"62","code":null,"number":"62","title":"Registered Surveyors Report","text":"A report must be submitted to the Principal Certifier at each of the following\napplicable stages of construction:\n(a) Set out before commencing excavation.\n(b) Floor slabs or foundation wall, before formwork or commencing\nbrickwork.\n(c) Completion of Foundation Walls - Before any construction of flooring,\ndetailing the location of the structure relative to adjacent boundaries\nand floor levels relative to the datum shown on the approved plans.\n(d) Completion of Floor Slab Formwork - Before pouring of concrete/walls\nconstruction, detailing the location of the structure relative to adjacent\nboundaries and floor levels relative to the datum shown on the approved\nplans. In multi -storey buildings a furt her survey must be provided at\neach subsequent storey.\n(e) Completion of any Pool Formwork - Before concreting of pool shell,\ndetailing the location of the pool relative to the adjacent boundaries and\nits height relative to the datum shown on the approved plans.\n(f) Completion of any Roof Framing - Before roof covered detailing\neaves/gutter setback from boundaries.\n(g) Completion of all Work - Detailing the location of the structure (including\neaves/gutters) relative to adjacent boundaries and its height relative to\nthe datum shown on the approved plans. A final Check Survey must\nindicate the reduced level of the main ridge.\nWork must not proceed beyond each stage until the Principal Certifier is satisfied\nthat the height and location of the building is proceeding in accordance with the\napproved plans.","stage":"during_work","stage_basis":"heading","page":28},{"label":"63","code":null,"number":"63","title":"Implementation of the site management plans while site work is being carried","text":"out:\na) the measures required by the construction site management plan and the\nerosion and sediment control plan (plans) must be implemented at all\ntimes, and\nb) a copy of these plans must be kept on site at all times and made available\nto council officers upon request.","stage":"during_work","stage_basis":"heading","page":29},{"label":"64","code":null,"number":"64","title":"Tree protection during work","text":"While site work is being carried out, all required tree protection measures must\nbe maintained in good condition in accordance with:\na) the construction site management plan required under this consent,\nb) the relevant requirements of AS 4970 Protection of trees on development\nsites,\nc) Council’s relevant development control plan (in force as at the date of\ndetermination of this consent) and\nd) any arborist’s report approved under this consent.\nThis includes maintaining adequate soil grades and ensuring all machinery,\nbuilders refuse, spoil and materials remain outside tree protection zones.","stage":"during_work","stage_basis":"heading","page":29},{"label":"65","code":null,"number":"65","title":"Waste management","text":"While site work is being carried out:\na) all waste management must be undertaken in accordance with the waste\nmanagement plan, and\nb) upon disposal of waste, records of the disposal must be compiled and\nprovided to the Certifier, or Council where a certifier is not required,\ndetailing the following:\ni) The contact details of the person(s) who removed the waste\nii) The waste carrier vehicle registration\niii) The date and time of waste collection\niv) A description of the waste (type of waste and estimated quantity)\nand whether the waste is to be reused, recycled or go to landfill\nv) The address of the disposal location(s) where the waste was taken\nvi) The corresponding tip docket/receipt from the site(s) to which the\nwaste is transferred, noting date and time of delivery, description\n(type and quantity) of waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order\nor Exemption, records in relation to that Order or Exemption must be\nmaintained and provided to the principal certifier and council.","stage":"during_work","stage_basis":"heading","page":29},{"label":"66","code":null,"number":"66","title":"Connection to the Network","text":"Where works within the road reserve are to be carried out by the developer, a\nRoad Opening Permit must be obtained from Council before the\ncommencement of any work.","stage":"during_work","stage_basis":"heading","page":30},{"label":"67","code":null,"number":"67","title":"Soil management","text":"While site work is being carried out, the principal certifier or council (where a\nprincipal certifier is not required) must be satisfied all soil removed from or\nimported to the site is managed in accordance with the following requirements:\na) all excavated material removed from the site must be classified in\naccordance with the epa’s waste classification guidelines before it is\ndisposed of at an approved waste management facility and the\nclassification and the volume of material removed must be reported to the\nprincipal certifier or council (where a principal certifier is not required).\nb) all fill material imported to the site must be:\ni) Virgin Excavated Natural Material as defined in Schedule 1 of the\nProtection of the Environment Operations Act 1997, or\nii) a material identified as being subject to a resource recovery exemption\nby the NSW EPA, or\niii) a combination of Virgin Excavated Natural Material as defined in\nSchedule 1 of the Protection of the Environment Operations Act 1997\nand a material identified as being subject to a resource recovery\nexemption by the NSW EPA.","stage":"during_work","stage_basis":"heading","page":30},{"label":"68","code":null,"number":"68","title":"Swimming Pools - Filling with Water","text":"The pool must not be filled until the safety fences have been completed in\naccordance with the approved plans and specifications and inspected by the\nPrincipal Certifier","stage":"during_work","stage_basis":"heading","page":30},{"label":"69","code":null,"number":"69","title":"Building Materials - Flood Prone Land","text":"All building materials used to construct the addition must be constructed using\nflood proof materials up to RL 15.2m AHD and this must be specified by the\nmanufacturer. All electrical services must also be located above this level. The\napplicant should refer to REDUCING VULNERABILITY OF BUILDINGS TO FLOOD\nDAMAGE (nsw.gov.au), Chapter 4.3.","stage":"during_work","stage_basis":"heading","page":30},{"label":"70","code":null,"number":"70","title":"","text":"Reduction of Rising Damp and Salt Attack In Buildings Constructed Prior To 1920\nTo avoid potential damage caused by rising damp and migrating salts the\nfollowing applies to the ground floor.\n(a) Concrete slab must not be laid directly on the ground either within the\nbuilding or external to the building directly adjacent to the exterior walls.","stage":"during_work","stage_basis":"heading","page":31},{"label":"71","code":null,"number":"71","title":"Retention of Internal Features","text":"Where sections of internal walls are to be removed to create openings between\noriginal rooms in the existing building, at least 1000mm of walls (including\narchitraves and skirting boards) at the ends adjoining other walls must be\nretained, to assist interp retation of the former layout of the building. Where\ninternal joinery features are to be conserved, any components replaced or\nreinstated must match the existing in profile and section size.","stage":"during_work","stage_basis":"heading","page":31},{"label":"72","code":null,"number":"72","title":"Discovery of relics and Aboriginal objects","text":"While site work is being carried out, if a person reasonably suspects a relic of\nAboriginal object is discovered:\na) the work in the area of the discovery must cease immediately;\nb) the following must be notified\ni) for a relic - the Heritage Council; or\nii) for an Aboriginal object - the person who is the authority for the\nprotection of Aboriginal objects and Aboriginal places in New South\nWales under the National Parks and Wildlife Act 1974, section 85.\nSite work may recommence at a time confirmed in writing by:\na) for a relic - the Heritage Council; or\nfor an Aboriginal object - the person who is the authority for the protection of\nAboriginal objects and Aboriginal places in New South Wales under the National\nParks and Wildlife Act 1974, section 85.","stage":"during_work","stage_basis":"heading","page":31},{"label":"73","code":null,"number":"73","title":"Compliance with Structural Engineering Report","text":"During construction the Structural Engineering Report prepared by Rebar\nEngineering Pty Ltd and dated 2 April 2026 should be complied with, particularly\nSections 6, 7 and 8.","stage":"during_work","stage_basis":"heading","page":31},{"label":"74","code":null,"number":"74","title":"BASIX Certificate","text":"All energy efficiency measures as detailed in the approved BASIX Certificate in the\nplans approved with the Development Consent, must be implemented before the\nissue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":32},{"label":"75","code":null,"number":"75","title":"BASIX Compliance Certificate","text":"A Compliance Certificate must be provided to the Principal Certifier regarding the\nimplementation of all energy efficiency measures as detailed in the approved\nBASIX Certificate before any Occupation Certificate is issued.","stage":"before_oc","stage_basis":"heading","page":32},{"label":"76","code":null,"number":"76","title":"Completion of Landscape Works and Tree Works","text":"The approved landscape works have identified that the side setback area between\nthe dwelling and boundary be nominated as landscaped area to ensure\ncompliance with the minimum landscape area requirements. In this regard, this\narea must be maintained as la ndscaped area and must only be used for growing\nplants, grasses and trees and must not include any building, structure or hard\npaving (including rainwater tanks, air -conditioning units of ground mounted hot\nwater systems).","stage":"before_oc","stage_basis":"heading","page":32},{"label":"77","code":null,"number":"77","title":"Minor Development","text":"Internal driveways and parking spaces must be adequately paved with concrete\nor bitumen, or interlocking pavers to provide a dust-free surface.","stage":"before_oc","stage_basis":"heading","page":32},{"label":"78","code":null,"number":"78","title":"Vehicular Crossing - Minor Development","text":"The vehicular crossing and footpath works must be constructed by a private\ncontractor at the expense of the applicant, in accordance with the Works Permit\nApproval issued by Council’s Engineering Design Services and in accordance with\nCouncil’s Driveway Specifications.\nAny existing vehicular crossing and laybacks which are redundant must be\nremoved. The kerb and gutter, any other footpath and turf areas must be restored\nat the expense of the applicant and in accordance with Council’s Driveway\nSpecifications.\nThe work must be completed before the issue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":32},{"label":"79","code":null,"number":"79","title":"Release of securities","text":"When Council receives an occupation certificate, an application may be lodged to\nrelease the securities held in accordance with Council’s Policy.","stage":"before_oc","stage_basis":"heading","page":33},{"label":"80","code":null,"number":"80","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":33},{"label":"81","code":null,"number":"81","title":"Removal of waste upon completion","text":"","stage":"before_oc","stage_basis":"heading","page":33},{"label":"82","code":null,"number":"82","title":"Electricity Supply","text":"Prior to the issue of any Occupation Certificate, evidence must be provided\ndemonstrating that the development has been connected to the Ausgrid network.","stage":"before_oc","stage_basis":"heading","page":33},{"label":"83","code":null,"number":"83","title":"Completion of public utility services","text":"Before the issue of the relevant occupation certificate, confirmation must be\nobtained from the relevant authority that any adjustment or augmentation of any\npublic utility services including gas, water, sewer, electricity, street lighting and\ntelecommunications, required as a result of the development, have been\ncompleted and this confirmation must be provided to the principal certifier.","stage":"before_oc","stage_basis":"heading","page":33},{"label":"84","code":null,"number":"84","title":"Restriction to User and Positive Covenant for Stormwater Management System","text":"Prior to the issue of any Occupation Certificate, the applicant must register a\nPositive Covenant and a Restriction as to User under section 88E and or section\n88B of the Conveyancing Act as appropriate in favour of Council, ensuring the\nongoing retention, maintenance and operation of the stormwater facility (on-site\ndetention, pump-out, charged lines, water sensitive urban design, surface flow\npath, finished pavement and ground levels etc.).\nWhere any drainage line or service conduit is to traverse any property other than\nthat which it serves, an appropriate easement will be required. In this case, the\napplicant must register an easement no less than 1200mm wide over the\nproposed drainage line or service concurrently with any subdivision registration.\nThe wording on the 88E and or 88B Instrument is to make reference to the Council\nfile where the Construction plans and the Work As Executed (as built), plans are\nheld. Typical wording can be obtained from Council's Specification for the\nManagement of Stormwater document.","stage":"before_oc","stage_basis":"heading","page":34},{"label":"85","code":null,"number":"85","title":"Maintenance Schedule - On-site Stormwater Management","text":"A Maintenance Schedule for the proposed on -site stormwater management\nmeasures must be prepared by a suitably qualified professional hydraulic\nengineer and submitted to Council. The Maintenance Schedule must outline the\nrequired maintenance works, how and when these will be done and who will be\ncarrying out these maintenance works.","stage":"before_oc","stage_basis":"heading","page":34},{"label":"86","code":null,"number":"86","title":"Post-construction dilapidation report","text":"Before the issue of an occupation certificate a post- construction dilapidation\nreport must be prepared by a suitably qualified engineer, to the satisfaction of\nthe principal certifier or council (where a principal certifier is not required),\ndetailing whether:\na) after comparing the pre-construction dilapidation report to the post-\nconstruction dilapidation report required under this condition, there has\nbeen any structural damage to any adjoining buildings; and\nb) where there has been structural damage to any adjoining buildings, that it\nis a result of the work approved under this development consent, and\na copy of the post-construction dilapidation report must be provided to council\n(where council is not the principal certifier or a principal certifier is not required)\nand to the relevant adjoining property owner(s).","stage":"before_oc","stage_basis":"heading","page":34},{"label":"87","code":null,"number":"87","title":"Works-as-executed plans and any other documentary evidence","text":"Before the issue of the relevant occupation certificate, works-as-executed plans,\nany compliance certificates and any other evidence confirming the following\ncompleted works must be submitted to the satisfaction of the principal certifier:\na) All stormwater drainage systems and storage systems, and\nb) The registration with LRS of the Positive Covenant and Restriction-on-use\ndocuments,\nc) A copy of the plans must be provided to council with the\nOccupation Certificate.","stage":"ongoing","stage_basis":"heading","page":35},{"label":"88","code":null,"number":"88","title":"Consolidation of Site","text":"The site must be consolidated into one allotment by a Plan of Consolidation\nbeing prepared by a Registered Surveyor. This Plan must be registered at the\nNSW Land Registry Services (LRS) prior to the issue of a final Occupation\nCertificate.","stage":"ongoing","stage_basis":"heading","page":35},{"label":"89","code":null,"number":"89","title":"Maintenance of Landscaping","text":"All trees and plants forming part of the landscaping must be maintained.\nMaintenance includes watering, weeding, removal of rubbish from tree bases,\nfertilising, pest and disease control, replacement of dead or dying plants and any\nother operations required to maintain healthy trees, plants and turfed areas.","stage":"ongoing","stage_basis":"heading","page":35},{"label":"90","code":null,"number":"90","title":"Maintenance of wastewater and stormwater treatment device","text":"During occupation and ongoing use of the building, all wastewater and\nstormwater treatment devices (including drainage systems, sumps and traps, and\non-site detention) must be regularly maintained to remain effective and in\naccordance with any positive covenant (if applicable).","stage":"ongoing","stage_basis":"heading","page":35},{"label":"91","code":null,"number":"91","title":"Entering and Exiting of Vehicles","text":"All vehicles must enter and exit the premises in a forward direction.","stage":"ongoing","stage_basis":"heading","page":35},{"label":"92","code":null,"number":"92","title":"Swimming Pools - Resuscitation Notice","text":"An expired air resuscitation warning notice complying with the Swimming Pools\nAct 1992 must be affixed in a prominent position adjacent to the pool.","stage":"ongoing","stage_basis":"heading","page":35},{"label":"93","code":null,"number":"93","title":"Private Swimming Pools & Spas - Pump Noise","text":"The swimming pool or spa pump and associated equipment must be located so\nthat the noise emitted does not exceed 5db(A) above the background level. If this\ncannot be achieved a ventilated and sound -proofed enclosure the pump to\nachieve the required noise levels.\nSwimming pool is to be installed with a timer that limits the recirculation and\nfiltration systems operation such that it does not emit noise that can be heard\nwithin a habitable room in any other residential premises (regardless of whether\nany door or window to that room is open):\n(a) before 8 am or after 8 pm on any Sunday or public holiday, or\n(b) before 7 am or after 8pm on any other day.","stage":"ongoing","stage_basis":"heading","page":36},{"label":"94","code":null,"number":"94","title":"Futsal court - Use","text":"The approved futsal court must be used solely for private recreational purposes\nancillary to the approved dwelling house.\nThe futsal court must not be used for any commercial, organised or public\nactivities, including but not limited to organised competitions, coaching, training\nsessions, sporting events or any form of commercial hire.","stage":"ongoing","stage_basis":"heading","page":36},{"label":"95","code":null,"number":"95","title":"Futsal court - Lighting","text":"No lighting is approved as part of this consent for the futsal court.\nNo lighting fixtures or associated electrical infrastructure are to be installed in\nconnection with the futsal court unless otherwise approved by a separate\ndevelopment consent granted by Council.","stage":"ongoing","stage_basis":"heading","page":36},{"label":"96","code":null,"number":"96","title":"No Structures on Street-Facing Roof Plan or Awning","text":"Solar hot water heater storage tanks, solar panels, ventilators, air conditioning\nunits, satellite dishes and antennae or the like are not to be placed on roof planes,\nparapets or street awnings of the building which are visible from a public street\n(other than rear laneways).","stage":"ongoing","stage_basis":"heading","page":36}]});
